<div class="ag-interior ag-art-page ag-art-article"><section class="ag-article-hero"><div class="wrap ag-article-grid"><div data-ag-reveal><span class="eyebrow"><?php ag_text($s,'eyebrow'); ?></span><h1><?php the_title(); ?></h1><p><?php echo esc_html($s['body']?:get_the_excerpt()); ?></p><div class="ag-article-meta"><time datetime="<?php echo esc_attr(get_the_date('c')); ?>"><?php echo esc_html(get_the_date()); ?></time><span><?php echo esc_html(get_post_meta(get_the_ID(),'_vatan_duration',true)); ?></span></div></div><?php ag_art_hero($s,'detail'); ?></div></section>
<section class="ag-section"><div class="wrap ag-editorial" data-article-body><?php $video=get_post_meta(get_the_ID(),'_vatan_video',true);$audio=get_post_meta(get_the_ID(),'_vatan_audio',true);if($video)echo '<video class="ag-video" controls playsinline preload="none" src="'.esc_url($video).'" poster="'.esc_url(ag_media_url($s['image'])).'"></video>';if($audio)echo '<audio class="media-player" controls preload="none" src="'.esc_url($audio).'"></audio>';the_content();$transcript=get_post_meta(get_the_ID(),'_vatan_transcript',true);if($transcript)echo '<h2>متن گفتگو</h2>'.wpautop(esc_html($transcript)); ?><div class="actions"><a class="home-route-link" href="<?php echo esc_url(vatan_url('media/')); ?>"><?php ag_text($s,'label'); ?> <span class="ag-symbol" aria-hidden="true">↗</span></a></div></div></section></div>
